  },
  command: {
    name: "command",
    className: "theme-command",
    density: "dense",
    controlHeight: 32,
    controlHeightSm: 28,
    textMin: 11,
    textBase: 13,
    textLarge: 16,
    textDisplay: 24,
    radius: 6,
    serifHeadings: false,
    edgeGuard: 8,
  },
  executive: {
    name: "executive",
    className: "theme-executive",
    density: "standard",
    controlHeight: 48,
    controlHeightSm: 40,
    textMin: 13,
    textBase: 16,
    textLarge: 22,
    textDisplay: 52,
    radius: 10,
    serifHeadings: false,
    edgeGuard: 8,
  },
};

/** Law 7 — theme is a property of the role, not a user preference. */
export const ROLE_THEME: Record<Role, ThemeName> = {
  rider: "sunlight",
  technician: "slate",
  qc: "slate",
  customer: "premium",
  onboarding: "premium",
  sales: "command",
  supplier: "command",
  admin: "command",
