import { createContext, useContext, useMemo, type ReactNode } from "react";
import { View } from "react-native";
import { vars } from "nativewind";

import { PALETTES } from "./palette";
import {
  ROLE_THEME,
  THEMES,
  type Role,
  type ThemeName,
  type ThemeSpec,
} from "./themes";

interface ThemeContextValue {
  role: Role;
  theme: ThemeName;
  spec: ThemeSpec;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

interface ThemeProviderProps {
  role: Role;
  children: ReactNode;
}

/**
 * Applies the role's theme. Wraps children in a View carrying the semantic
 * tokens as CSS variables, so every descendant resolves `bg-primary`,
 * `text-foreground` and friends against this role's palette.
 *
 * Law 7 — the theme follows the role, not a user preference.
 */
export function ThemeProvider({ role, children }: ThemeProviderProps) {
  const value = useMemo<ThemeContextValue>(() => {
    const theme = ROLE_THEME[role];
    return { role, theme, spec: THEMES[theme] };
  }, [role]);

  const style = useMemo(() => vars(PALETTES[value.theme]), [value.theme]);

  return (
    <ThemeContext.Provider value={value}>
      <View style={style} className="flex-1 bg-background">
        {children}
      </View>
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error(
      "useTheme() was called outside a ThemeProvider. Every screen renders under exactly one role.",
    );
  }
  return ctx;
}

/** Convenience for components that only need sizing, not role identity. */
export function useThemeSpec(): ThemeSpec {
  return useTheme().spec;
}
