const btn = [...document.querySelectorAll('[role="button"]')].find(b => (b.getAttribute('aria-label')||'').includes('कॅप्चर'));
const sw = [...document.querySelectorAll('[role="radio"]')][0];
const help = [...document.querySelectorAll('[role="button"]')].find(b => (b.getAttribute('aria-label')||'').includes('मदत'));
({
  captureButton: btn ? btn.getBoundingClientRect().height : 'not found',
  captureLabel: btn ? btn.getAttribute('aria-label') : null,
  languageChip: sw ? sw.getBoundingClientRect().height : 'not found',
  helpBubblePresent: !!help,
  viewportWidth: window.innerWidth,
  bodyScrollWidth: document.body.scrollWidth
})

function find(txt){ return [...document.querySelectorAll('div,span')].find(e => e.children.length===0 && e.textContent.trim()===txt); }
const title = find('Guide rail alignment');
const muted = find('Fishplate joint close-up');
const root = document.querySelector('#root') || document.body;
function probe(el){ if(!el) return 'not found'; const cs=getComputedStyle(el); return { color: cs.color, cls: el.className && el.className.baseVal!==undefined ? el.className.baseVal : el.className }; }
({
  defaultToneText: probe(title),
  mutedToneText: probe(muted),
  fgVarOnTitle: title ? getComputedStyle(title).getPropertyValue('--foreground') : null,
  mutedVarOnTitle: title ? getComputedStyle(title).getPropertyValue('--muted-foreground') : null,
  hasTextForegroundRule: [...document.styleSheets].some(s => { try { return [...s.cssRules].some(r => r.selectorText && r.selectorText.includes('text-foreground')); } catch(e){ return false; } })
})

