function find(txt){ return [...document.querySelectorAll('div,span')].find(e => e.children.length===0 && e.textContent.trim()===txt); }
const title = find('Guide rail alignment');
const themeEl = [...document.querySelectorAll('*')].find(e => typeof e.className === 'string' && e.className.includes('bg-background'));
const painted = [];
let el = title, depth = 0;
while (el) {
  const cs = getComputedStyle(el);
  const bg = cs.backgroundColor;
  if (bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
    painted.push({ depth, tag: el.tagName, cls: (typeof el.className === 'string' ? el.className : '').slice(0,80), bg });
  }
  el = el.parentElement; depth++;
}
({
  themeElContainsTitle: themeEl ? themeEl.contains(title) : 'no theme el',
  totalDepth: depth,
  paintedAncestors: painted,
  titleRect: title.getBoundingClientRect(),
  themeRect: themeEl ? themeEl.getBoundingClientRect() : null
})

