import "../src/design/global.css";

import {
  DarkTheme,
  ThemeProvider as NavigationThemeProvider,
} from "@react-navigation/native";
import { Stack } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { SafeAreaProvider } from "react-native-safe-area-context";

import { I18nProvider } from "@/i18n";
import { deviceLanguage } from "@/i18n/device";

/**
 * React Navigation paints its own screen background (rgb(242,242,242) in the
 * default light theme) inside our theme wrapper, which washed out every dark
 * role theme. The role's ThemeProvider owns the background, so navigation is
 * handed a fully transparent one and gets out of the way.
 */
const TRANSPARENT_NAVIGATION_THEME = {
  ...DarkTheme,
  colors: { ...DarkTheme.colors, background: "transparent", card: "transparent" },
};

