    <SafeAreaProvider>
      <NavigationThemeProvider value={TRANSPARENT_NAVIGATION_THEME}>
        <I18nProvider initialLanguage={deviceLanguage()}>
          <Stack
            screenOptions={{
              headerShown: false,
              contentStyle: { backgroundColor: "transparent" },
            }}
          />
          <StatusBar style="auto" />
        </I18nProvider>
      </NavigationThemeProvider>
    </SafeAreaProvider>
  );
}
