import { ScrollView, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { Feather } from "@expo/vector-icons";

import { MapShell } from "@/components/anatomy";
import { Card, LanguageSwitch, Pill, Text } from "@/components/ui";
import { ADMIN_ALERTS, ADMIN_MAP } from "@/contract/fixtures";
import { useFormat, useT } from "@/i18n";

const PRIORITY_TONE = {
  P0: "danger",
  P1: "warning",
  P2: "warning",
} as const;

const PRIORITY_BORDER = {
  P0: "border-l-danger",
  P1: "border-l-warning",
  P2: "border-l-warning",
} as const;

/**
 * A1 Live city map plus A2 Alert queue. Command theme, built for density.
 *
 * The console shows exceptions, not operations: six things wrong, not four
 * hundred healthy jobs. Every alert card carries what the system already did
 * automatically and two or three one-tap decisions, because the target is a
 * median resolution under ninety seconds.
 */
export default function AdminConsoleScreen() {
  const t = useT();
  const f = useFormat();

  return (
    <SafeAreaView className="flex-1" edges={["top", "left", "right"]}>
      <View className="flex-row items-center gap-3 border-b border-line px-4 py-2">
        <Text variant="body" weight="600">
          AIEC
        </Text>
        <Text variant="caption" tone="muted">
          Pune
        </Text>
        <View className="flex-1 rounded-md bg-surface px-3 py-1.5">
          <Text variant="caption" tone="subtle">
            {t("admin.searchAnyId")}
          </Text>
        </View>
        <Pill label={"P0 " + ADMIN_MAP.counts.p0} tone="danger" />
        <Pill label={"P1 " + ADMIN_MAP.counts.p1} tone="warning" />
        <LanguageSwitch />
      </View>

      <View className="h-56">
        <MapShell pins={ADMIN_MAP.pins}>
          <View className="absolute left-3 top-3 flex-row gap-1.5">
            <Pill label={t("admin.alertsOnly")} tone="primary" />
          </View>
        </MapShell>
      </View>

      <View className="flex-row items-center justify-between border-y border-line px-4 py-2">
        <Text variant="body" weight="600">
          {t("admin.alertQueue")}
        </Text>
        <Text variant="caption" tone="muted">
          {t("admin.medianResolution", { seconds: 71 })}
        </Text>
      </View>

      <ScrollView contentContainerClassName="gap-2 p-3">
        {ADMIN_ALERTS.map((alert) => (
          <Card
            key={alert.id}
            bordered={false}
            className={"border-l-4 bg-surface-raised p-3 " + PRIORITY_BORDER[alert.priority]}
            style={{ borderRadius: 0 }}
          >
            <View className="flex-row items-center justify-between gap-2">
              <Text
                variant="caption"
                weight="600"
                tone={PRIORITY_TONE[alert.priority]}
              >
                {alert.priority + " · " + alert.title}
              </Text>
              <Text variant="caption" tone="subtle" style={{ fontFamily: "monospace" }}>
                {alert.id}
              </Text>
            </View>

            <Text variant="body" className="mt-1">
              {alert.detail}
            </Text>

            <View className="mt-1.5 flex-row items-start gap-1.5">
              <Feather name="cpu" size={13} className="text-subtle" />
              <Text variant="caption" tone="subtle" className="flex-1">
                {alert.autoAction}
              </Text>
            </View>

            <View className="mt-2 flex-row gap-1.5">
              {alert.decisions.map((decision) => (
                <Pill key={decision} label={decision} />
              ))}
            </View>
          </Card>
        ))}
      </ScrollView>

      <View className="flex-row border-t border-line">
        <View className="flex-1 px-3 py-2">
          <Text variant="caption" tone="subtle">
            Tokens today
          </Text>
          <Text variant="body" weight="600">
            {f.paise(ADMIN_MAP.money.tokensPaise)}
          </Text>
        </View>
        <View className="flex-1 px-3 py-2">
          <Text variant="caption" tone="subtle">
            Escrow held
          </Text>
          <Text variant="body" weight="600">
            {f.paise(ADMIN_MAP.money.escrowPaise)}
          </Text>
        </View>
        <View className="flex-1 px-3 py-2">
          <Text variant="caption" tone="subtle">
            Reward cap
          </Text>
          <Text variant="body" weight="600" tone="success">
            {f.percent(ADMIN_MAP.money.rewardCapUsed) + " / " + f.percent(ADMIN_MAP.money.rewardCapLimit)}
          </Text>
        </View>
      </View>
    </SafeAreaView>
  );
}

