          <ListRow
            key={lead.id}
            title={lead.site}
            subtitle={lead.id}
            monoSubtitle
            icon={lead.escalated ? "headphones" : "cpu"}
            iconTone={lead.escalated ? "text-warning" : BAND_TONE[lead.band]}
