({
  window: { w: window.innerWidth, h: window.innerHeight },
  root: root ? { w: Math.round(root.getBoundingClientRect().width), h: Math.round(root.getBoundingClientRect().height), id: root.id, cls: (root.className||'').slice(0,50) } : null,
