  devicePixelRatio: window.devicePixelRatio
})

async function check(path) {
  history.pushState({}, '', path);
  window.dispatchEvent(new PopStateEvent('popstate'));
  await new Promise(r => setTimeout(r, 900));
  const txt = document.body.innerText.replace(/\s+/g, ' ').trim();
  return { path, chars: txt.length, overflow: document.body.scrollWidth - window.innerWidth, sample: txt.slice(0, 110) };
}
const out = [];
for (const p of ['/admin/config', '/admin/alerts', '/admin/approvals', '/supplier', '/sales', '/onboarding']) {
  out.push(await check(p));
}
