import { useState } from "react";
import { View, type LayoutChangeEvent } from "react-native";
import Svg, { Circle, Path, Rect } from "react-native-svg";

import { MAP_COLORS } from "@/design/palette";
import type { MapStatus } from "@/design/themes";

export interface MapPin {
  id: string;
  /** Normalised 0..1 within the viewport. Becomes lng/lat under MapLibre. */
  x: number;
  y: number;
  status: MapStatus;
  /** Another rider's pin — dimmed, so two riders never capture one shaft. */
  foreign?: boolean;
}

export interface HeatCell {
  x: number;
  y: number;
  w: number;
  h: number;
  /** 0..1 — the AI's opportunity score for this 250m grid cell. */
  intensity: number;
}

/**
 * Law 2 — the map is the app. Every role opens onto this; lists are only ever
 * a toggle on top of it.
 *
 * Geometry is normalised 0..1 rather than pixel-based, so swapping the interior
 * for MapLibre GL + PMTiles later is a change inside this file only. The pin
 * palette is deliberately imported from the universal legend: a red pin means
 * the same thing to the rider and to the owner.
 */
export function MapShell({
  pins = [],
  trail = [],
  heat = [],
  self,
  children,
}: {
  pins?: MapPin[];
  trail?: [number, number][];
  heat?: HeatCell[];
  self?: { x: number; y: number };
  children?: React.ReactNode;
}) {
  const [size, setSize] = useState({ width: 0, height: 0 });

  const onLayout = (e: LayoutChangeEvent) => {
    const { width, height } = e.nativeEvent.layout;
    setSize({ width, height });
  };

  const { width: w, height: h } = size;
  const px = (n: number) => n * w;
  const py = (n: number) => n * h;

  const trailPath = trail
    .map(([x, y], i) => `${i === 0 ? "M" : "L"} ${px(x)} ${py(y)}`)
    .join(" ");

  return (
    <View className="flex-1 bg-surface" onLayout={onLayout}>
      {w > 0 && h > 0 ? (
        <Svg width={w} height={h} accessibilityLabel="Map">
          {[0.18, 0.42, 0.68, 0.9].map((y) => (
            <Rect
              key={`h${y}`}
              x={0}
              y={py(y)}
              width={w}
              height={8}
              fill="rgba(120,120,110,0.14)"
            />
          ))}
          {[0.22, 0.55, 0.82].map((x) => (
            <Rect
              key={`v${x}`}
              x={px(x)}
              y={0}
              width={8}
              height={h}
              fill="rgba(120,120,110,0.14)"
            />
          ))}

          {heat.map((cell, i) => (
            <Rect
              key={`heat${i}`}
              x={px(cell.x)}
              y={py(cell.y)}
              width={px(cell.w)}
              height={py(cell.h)}
              rx={8}
              fill={`rgba(234,88,12,${0.1 + cell.intensity * 0.3})`}
            />
          ))}

          {trail.length > 1 ? (
            <Path
              d={trailPath}
              stroke={MAP_COLORS.sales}
              strokeWidth={4}
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
          ) : null}

          {pins.map((pin) => (
            <Circle
              key={pin.id}
              cx={px(pin.x)}
              cy={py(pin.y)}
              r={7}
              fill={MAP_COLORS[pin.status]}
              opacity={pin.foreign ? 0.35 : 1}
            />
          ))}

          {self ? (
            <>
              <Circle cx={px(self.x)} cy={py(self.y)} r={14} fill="rgba(59,130,246,0.25)" />
              <Circle cx={px(self.x)} cy={py(self.y)} r={7} fill={MAP_COLORS.sales} />
            </>
          ) : null}
        </Svg>
      ) : null}

      <View className="absolute inset-0">{children}</View>
    </View>
  );
}

