27	/** Local equirectangular projection. Accurate enough across a single city. */
28	function project(
29	  point: GeoPoint,
30	  center: GeoPoint,
31	  metresPerPixel: number,
32	  width: number,
33	  height: number,
34	) {
35	  const dxMetres = (point.lng - center.lng) * metresPerDegreeLng(center.lat);
36	  const dyMetres = (point.lat - center.lat) * METRES_PER_DEGREE_LAT;
37	  return {
38	    x: width / 2 + dxMetres / metresPerPixel,
39	    y: height / 2 - dyMetres / metresPerPixel,
40	  };
41	}
