33	/** Runs now if the style is already parsed, otherwise once it is. */
34	function whenStyleReady(instance: maplibregl.Map, run: () => void) {
35	  if (instance.isStyleLoaded()) {
36	    run();
37	    return () => {};
38	  }
39	  const handler = () => run();
40	  instance.once("load", handler);
41	  return () => {
42	    instance.off("load", handler);
43	  };
44	}
